import React, { useState } from 'react';
import { getProductImage } from '../data/menuData';

const weightLabels = { "1KG": "1 KG", "1/2KG": "½ KG", "250GM": "250 GM" };

function ProductCard({ product, onAddToCart }) {
  const [selectedWeight, setSelectedWeight] = useState("1KG");
  const [isHovered, setIsHovered] = useState(false);
  const [added, setAdded] = useState(false);
  const [imgError, setImgError] = useState(false);

  const handleAdd = () => {
    onAddToCart(product, selectedWeight);
    setAdded(true);
    setTimeout(() => setAdded(false), 1200);
  };

  return (
    <div
      className={`group bg-white rounded-2xl overflow-hidden shadow-lg hover:shadow-2xl transition-all duration-500 ease-out ${isHovered ? 'scale-[1.03] -translate-y-2' : ''}`}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {/* Image with gradient overlay */}
      <div className="relative h-48 overflow-hidden bg-gradient-to-br from-orange-100 to-amber-100">
          src={getProductImage(product)}
          alt={product.name}
          className={`w-full h-full object-cover transition-transform duration-700 ${isHovered ? 'scale-110' : 'scale-100'}`}
          loading="lazy"
        />
        <div className={`absolute inset-0 bg-gradient-to-t from-black/30 to-transparent transition-opacity duration-300 ${isHovered ? 'opacity-100' : 'opacity-0'}`}></div>
        {/* Category Badge */}
        <span className="absolute top-3 left-3 bg-white/90 backdrop-blur px-3 py-1 rounded-full text-xs font-semibold text-gray-700 shadow">
          {product.category}
        </span>
      </div>

      {/* Content */}
      <div className="p-4">
        <h3 className="text-lg font-bold text-gray-800 mb-3 group-hover:text-red-700 transition-colors">{product.name}</h3>

        {/* Weight Selector */}
        <div className="flex gap-1.5 mb-3">
          {Object.entries(product.prices).map(([weight, price]) => (
            <button
              key={weight}
              onClick={() => setSelectedWeight(weight)}
              className={`flex-1 py-2 px-1 rounded-lg text-xs font-semibold transition-all duration-200 ${
                selectedWeight === weight
                  ? 'bg-red-700 text-white shadow'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              <div>{weightLabels[weight]}</div>
              <div className="mt-0.5">₹{price}</div>
            </button>
          ))}
        </div>

        {/* Price Display */}
        <div className="flex items-center justify-between mb-3 bg-red-50 rounded-lg px-3 py-2">
          <span className="text-sm text-gray-600">{weightLabels[selectedWeight]}</span>
          <span className="text-xl font-bold text-red-700">₹{product.prices[selectedWeight]}</span>
        </div>

        {/* Add to Cart Button */}
        <button
          onClick={handleAdd}
          disabled={added}
          className={`w-full py-3 rounded-xl font-bold text-sm transition-all duration-300 ${
            added
              ? 'bg-green-500 text-white scale-105'
              : isHovered
                ? 'bg-gradient-to-r from-red-700 to-red-500 text-white shadow-lg'
                : 'bg-gray-100 text-gray-700 hover:bg-red-700 hover:text-white'
          }`}
        >
          <span className="flex items-center justify-center gap-2">
            {added ? '✅ Added!' : '🛒 Add to Cart'}
          </span>
        </button>
      </div>
    </div>
  );
}

export default ProductCard;
